probe_command:
PYTHONPATH="$PWD:$PWD/services/mlx-worker-python" uv run --project services/mlx-worker-python python -c "import json, sys, tempfile, time; from pathlib import Path; repo_root = Path.cwd(); sys.path.insert(0, str(repo_root)); sys.path.insert(0, str(repo_root / 'services/mlx-worker-python')); from tests.test_maintenance_service import FastBenchmarkBackend, FakeBenchmarkHFDatasetFetcher, build_service; from packages.protocol.python.worker.v1 import maintenance_pb2; from worker.model_registry.catalog import WorkerModelCatalog; from worker.productization.benchmark_suites import BenchmarkSuiteCatalog; from worker.registry import WorkerRegistry; from worker.runtime.mlx_text_runtime import MLXTextRuntime; elapsed_samples = []; read_samples = [];
for _ in range(3):
    with tempfile.TemporaryDirectory(prefix='melix-pr-perf-bench-report-') as temp_dir:
        registry = WorkerRegistry(runtime=MLXTextRuntime(backend=FastBenchmarkBackend()), model_catalog=WorkerModelCatalog())
        loaded = registry.load_model(WorkerModelCatalog.dev_text_model())
        service = build_service(Path(temp_dir), registry=registry)
        service._core._benchmark_suite_catalog = BenchmarkSuiteCatalog(hf_dataset_fetcher=FakeBenchmarkHFDatasetFetcher())
        tracker = {'count': 0}
        original_read_text = Path.read_text
        def tracked_read_text(self, *args, **kwargs):
            if self.name == 'bench-report.md' and self.parent.name.startswith('model-ops-'):
                tracker['count'] += 1
            return original_read_text(self, *args, **kwargs)
        Path.read_text = tracked_read_text
        try:
            started = time.perf_counter()
            list(service.RunBench(maintenance_pb2.RunBenchRequest(model_handle=loaded.handle, suites=['smoke'], parameters={'require_live_model': 'true'}), context=None))
            elapsed_samples.append((time.perf_counter() - started) * 1000.0)
        finally:
            Path.read_text = original_read_text
        read_samples.append(float(tracker['count']))
print(json.dumps({'elapsed_ms_mean': round(sum(elapsed_samples) / len(elapsed_samples), 3), 'bench_report_read_calls_mean': round(sum(read_samples) / len(read_samples), 3)}, sort_keys=True))"
